insert into public.heroes (id,slug,name,category,description,portrait,stats,abilities,unlock_requirement) values
('tostik','tostik','Ер Төстік','Қиял-ғажайып ертегі','Жер асты әлеміне сапар шеккен ертегі қаһарманы. Оның ерлігі мен достарына адалдығы қиындықтарды жеңуге көмектеседі.','/art/hero-0.webp','{"strength":70,"wisdom":75,"courage":90,"agility":80,"eloquence":65}','["Шалқұйрықтың серпіні"]','0'),
('alpamys','alpamys','Алпамыс батыр','Батырлық жыр','«Алпамыс батыр» эпосының қаһарманы. Елін қорғау, адалдық пен төзімділік — оның жырдағы басты қасиеттері.','/art/hero-1.webp','{"strength":95,"wisdom":70,"courage":95,"agility":70,"eloquence":65}','["Берік қалқан"]','100'),
('kobylandy','kobylandy','Қобыланды батыр','Батырлық жыр','«Қобыланды батыр» жырындағы ерлік пен табандылықтың бейнесі. Эпикалық дәстүрдің кейіпкері.','/art/hero-2.webp','{"strength":90,"wisdom":85,"courage":90,"agility":80,"eloquence":60}','["Дала стратегиясы"]','250'),
('kendebay','kendebay','Керқұла атты Кендебай','Қиял-ғажайып ертегі','Мейірімділігі мен әділдігі арқылы танылған ертегі кейіпкері. Керқұла атымен бірге мұқтаж жандарға көмектеседі.','/art/hero-3.webp','{"strength":85,"wisdom":75,"courage":85,"agility":95,"eloquence":60}','["Керқұланың жылдамдығы"]','400'),
('tazsha','tazsha','Тазша бала','Халық ертегісі','Ақылы мен тапқырлығы арқылы қиын сұрақтарға жауап табатын халық ертегілерінің кейіпкері.','/art/hero-4.webp','{"strength":45,"wisdom":98,"courage":80,"agility":80,"eloquence":95}','["Тапқыр ой"]','550'),
('aldar','aldar','Алдар көсе','Халық аңызы','Халық әңгімелеріндегі тапқыр кейіпкер. Оның әзілге толы оқиғалары сараңдық пен әділетсіздікті әшкерелейді.','/art/hero-5.webp','{"strength":50,"wisdom":95,"courage":75,"agility":85,"eloquence":98}','["Сөздің күші"]','700')
